// ------------------------------------------------------------
// Config / state
// ------------------------------------------------------------

const LANES = [-1.55, 0, 1.55]
const BPM = 128
const BEAT = 60 / BPM
const IS_TOUCH = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0
const IS_MOBILE = IS_TOUCH || innerWidth < 860
const HAS_VIBRATION = typeof navigator.vibrate === 'function'

const save = {
  get(key, fallback) {
    try {
      return localStorage.getItem(key) ?? fallback
    } catch {
      return fallback
    }
  },
  set(key, value) {
    try {
      localStorage.setItem(key, value)
    } catch {
      // private mode / storage blocked
    }
  },
}

const app = {
  state: 'menu',
  selected: 'mika',
  best: Number(save.get('femboys.best', '0')) || 0,
  time: 0,
  menuSpin: 0,
  menuCharX: 0,
  shake: 0,
  flashPulse: 0,
  lastHud: {},
  countdownTimers: [],
  tutorialTimer: null,
  bannerTimer: null,
  toastTimer: null,
  gameoverTimer: null,
  startedAt: 0,
  currentZone: 0,
  gameoverTurn: 0,
}

const G = {
  lane: 1,
  targetLane: 1,
  playerX: 0,
  y: 0,
  vy: 0,
  onGround: true,
  speed: 11.5,
  distance: 0,
  score: 0,
  combo: 0,
  bestCombo: 0,
  multiplier: 1,
  lives: 3,
  style: 0,
  superTime: 0,
  invuln: 0,
  runTime: 0,
